"use strict"

/** @typedef {import("./Resolver")} Resolver */
/** @typedef {import("./Resolver").ResolveRequest} ResolveRequest */
/** @typedef {import("./Resolver").ResolveStepHook} ResolveStepHook */
/**
 * @param {string | ResolveStepHook} source source
 * @param {string | ResolveStepHook} target target
 */

/**
 * @param {Resolver} resolver the resolver
 * @returns {void}
 */ /** @type {string} */
/** @type {ResolveRequest} */

module.exports = class CloneBasenamePlugin {
  constructor(source, target) {
    this.source = source
    this.target = target
  }
  apply(resolver) {
    const target = resolver.ensureHook(this.target)
    resolver
      .getHook(this.source)
      .tapAsync("CloneBasenamePlugin", (request, resolveContext, callback) => {
        const requestPath = request.path
        const filename = resolver.basename(requestPath)
        const filePath = resolver.join(requestPath, filename)
        const obj = {
          ...request,
          path: filePath,
          relativePath:
            request.relativePath &&
            resolver.join(request.relativePath, filename),
        }
        resolver.doResolve(
          target,
          obj,
          `using path: ${filePath}`,
          resolveContext,
          callback,
        )
      })
  }
}
